{
  "summary": "The old harness cannot reach the new keyed unpack diagnostic. It also retains coverage gaps in the unpack format contract that existed before the change.",
  "coverage_complete": false,
  "coverage_evidence": [],
  "claims": [
    {
      "claim_id": "keyed-string-member-error",
      "necessary": "yes",
      "necessity_reason": "A typed object-member mismatch can now report the member key through the shared unpack operation with an error destination. The old harness parses a suitable object but fixes both its format and unpack wrapper, leaving that supported behavior unreachable.",
      "before": {
        "requirement": "Report the member key in a wrong-type string error for an object member.",
        "applicability": "not_applicable",
        "harness_status": "not_applicable",
        "reason": "The earlier string validator reported the type without the member key.",
        "source_evidence": [
          {
            "unit_id": "u-9cefb4424b22803c6417",
            "start_line": 687,
            "end_line": 691,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-fb2b0902161308341cab",
            "start_line": 528,
            "end_line": 555,
            "role": "dependency",
            "dependency_reason": "Object lookup selected the member but did not pass its key to the validator."
          }
        ]
      },
      "after": {
        "requirement": "Report the member key when string-format validation rejects a non-string object member and an unpack error destination is supplied.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "For input 0x00 followed by {\"data\":42}, a typed unpack with an error destination can report key data. The harness uses {s?o}, which does not check for a string, and json_unpack supplies no unpack error destination.",
        "source_evidence": [
          {
            "unit_id": "u-6ea6a2b1b78051d20b1c",
            "start_line": 690,
            "end_line": 695,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-492d1cbf05366c92bf62",
            "start_line": 530,
            "end_line": 557,
            "role": "dependency",
            "dependency_reason": "Object unpacking passes the selected member key to typed validation."
          },
          {
            "unit_id": "u-360317144be11f0fe150",
            "start_line": 935,
            "end_line": 945,
            "role": "dependency",
            "dependency_reason": "The unpack wrapper with an error parameter forwards that destination to the shared implementation."
          },
          {
            "unit_id": "u-1e97954ace92371dd97b",
            "start_line": 947,
            "end_line": 956,
            "role": "dependency",
            "dependency_reason": "The wrapper called by the harness instead forwards a null error destination."
          }
        ]
      },
      "same_blocker": "not_applicable",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 18,
          "end_line": 87,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The keyed diagnostic was unavailable before the change. Afterward, the fixed format and missing unpack error destination prevent the same entry from reaching it.",
      "missing_information": [],
      "change_ids": ["g0003", "g0006"]
    },
    {
      "claim_id": "typed-object-string",
      "necessary": "yes",
      "necessity_reason": "String-format validation of an object member belongs to the entry's unpack format surface. The old harness always uses o for that member.",
      "before": {
        "requirement": "Reject a non-string object member selected by a string value format.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "A parsed {\"data\":1} can supply the member, but {s?o} selects generic extraction instead of string validation.",
        "source_evidence": [
          {
            "unit_id": "u-9cefb4424b22803c6417",
            "start_line": 687,
            "end_line": 722,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-fb2b0902161308341cab",
            "start_line": 528,
            "end_line": 555,
            "role": "dependency",
            "dependency_reason": "The object helper passes the selected member to format-specific unpacking."
          }
        ]
      },
      "after": {
        "requirement": "Reject a non-string object member selected by a string value format.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The type check remains supported, while the same harness still selects o for the member.",
        "source_evidence": [
          {
            "unit_id": "u-6ea6a2b1b78051d20b1c",
            "start_line": 690,
            "end_line": 726,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-492d1cbf05366c92bf62",
            "start_line": 530,
            "end_line": 557,
            "role": "dependency",
            "dependency_reason": "The object helper still passes the selected member to format-specific unpacking."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
