          "start_line": 57,
          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The fixed {s?o} format blocks the same member string check on both sides; the new key wording does not create this type-validation gap.",
      "missing_information": [],
      "change_ids": ["g0006"]
    },
    {
      "claim_id": "required-object-member",
      "necessary": "yes",
      "necessity_reason": "The source supports rejecting a missing required object member, but the harness marks its only looked-up member optional.",
