          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The same optional marker blocks required-member rejection before and after.",
      "missing_information": [],
      "change_ids": ["g0003"]
    },
    {
      "claim_id": "strict-object-members",
      "necessary": "yes",
      "necessity_reason": "Strict object unpacking can reject an unconsumed member, but the harness selects neither an object strict marker nor a strict unpack flag.",
      "before": {
        "requirement": "Reject an object member left unconsumed by a strict object format.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The object format lacks ! and json_unpack passes zero flags.",
        "source_evidence": [
