            "start_line": 937,
            "end_line": 945,
            "role": "dependency",
            "dependency_reason": "The called wrapper supplies zero unpack flags."
          }
        ]
      },
      "after": {
        "requirement": "Reject an object member left unconsumed by a strict object format.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The strict object check remains, while the format and zero flags remain fixed. An input with data and extra members cannot select this check.",
        "source_evidence": [
          {
            "unit_id": "u-492d1cbf05366c92bf62",
            "start_line": 518,
            "end_line": 521,
