            "end_line": 955,
            "role": "dependency",
            "dependency_reason": "The called wrapper still supplies zero unpack flags."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 18,
          "end_line": 32,
          "role": "dependency",
          "dependency_reason": "Fuzzer bytes can supply an object with an extra member."
        },
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 57,
          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "Both versions support strict object validation, and the same format and flags omit it. The harness's [o!] checks array length, not object members.",
      "missing_information": [],
      "change_ids": ["g0002", "g0003"]
    },
    {
      "claim_id": "typed-scalar-formats",
      "necessary": "yes",
      "necessity_reason": "The unpack format protocol supports typed scalar extraction and validation. Every value format in the harness is o, so no fuzzer input can select a typed scalar format.",
      "before": {
        "requirement": "Reach typed scalar extraction or validation through the unpack format protocol.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "For example, [1] could be unpacked with [i!] into an int, but the harness fixes the element format to o.",
        "source_evidence": [
          {
            "unit_id": "u-9cefb4424b22803c6417",
