            "start_line": 641,
            "end_line": 663,
            "role": "dependency",
            "dependency_reason": "Array elements are dispatched according to their selected value format."
          }
        ]
      },
      "after": {
        "requirement": "Reach typed scalar extraction or validation through the unpack format protocol.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The typed formats remain supported, and the old harness still selects o for every unpacked value.",
        "source_evidence": [
