            "end_line": 665,
            "role": "dependency",
            "dependency_reason": "Array elements remain dispatched according to their selected value format."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 18,
          "end_line": 32,
          "role": "dependency",
          "dependency_reason": "Fuzzer bytes can supply typed scalar values inside parsed JSON."
        },
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 57,
          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The fixed o value formats exclude typed scalar dispatch on both sides. The s in {s?o} consumes a key argument; it does not select the member value's format.",
      "missing_information": [],
      "change_ids": ["g0006", "g0007", "g0008", "g0009", "g0010", "g0011", "g0012"]
    },
