      "claim_id": "retained-O-extraction",
      "necessary": "yes",
      "necessity_reason": "O is a supported unpack format with a distinct retained-reference result. The harness fixes every unpack value format to borrowed o.",
      "before": {
        "requirement": "Extract a selected JSON value with O and release the acquired reference.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The source increments the reference for O, but the harness never selects O.",
